import csv,re,json,sys
inv={r['id']:r['amount'] for r in csv.DictReader(open('backoffice/invoices.csv',encoding='utf-8'))}
pays={}
for r in csv.DictReader(open('backoffice/bank_statement_june.csv',encoding='utf-8')):
    m=re.search(r'(?:inv-?|invoice )(\d{4})',r['memo'],re.I)
    if not m: continue
    pays.setdefault('INV-'+m[1],[]).append(r['amount'])
out={'unpaid':[i for i in inv if i not in pays],'duplicated':[i for i in inv if len(pays.get(i,[]))>1],
 'mismatched':[{'id':i,'invoiced':float(inv[i]),'paid':float(pays[i][0])} for i in inv if len(pays.get(i,[]))==1 and pays[i][0]!=inv[i]]}
print([k for k in pays if k not in inv])
json.dump(out,open('result.json','w'),indent=2);print(json.dumps(out))
